import { useState } from 'react';
import axios from 'axios';
import { toast } from 'sonner';
import { motion } from 'framer-motion';
import { CONTACT } from '@/constants/testIds/portfolio';
import { FadeUp } from './Reveal';

const API = `${process.env.REACT_APP_BACKEND_URL}/api`;

export const Contact = () => {
  const [form, setForm] = useState({ name: '', email: '', message: '' });
  const [loading, setLoading] = useState(false);

  const update = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));

  const submit = async (e) => {
    e.preventDefault();
    if (!form.name || !form.email || !form.message) {
      toast.error('Please fill in every field.');
      return;
    }
    setLoading(true);
    try {
      await axios.post(`${API}/contact`, form);
      toast.success('Message sent — we\u2019ll be in touch soon.');
      setForm({ name: '', email: '', message: '' });
    } catch (err) {
      toast.error('Something went wrong. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <section id="contact" data-testid={CONTACT.section} className="px-6 md:px-12 py-28 md:py-40">
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 lg:gap-20">
        <div className="lg:col-span-5">
          <FadeUp>
            <span className="text-[11px] tracking-[0.3em] uppercase text-[#E11D48]">[ Get in touch ]</span>
            <h2 className="font-display font-semibold text-6xl md:text-8xl uppercase leading-[0.88] mt-5">
              Let&apos;s<br />shoot
            </h2>
            <p className="mt-8 text-white/60 leading-relaxed max-w-sm">
              Got a script, a collaboration, or a wild idea? Drop us a line and let&apos;s make
              something worth watching.
            </p>
          </FadeUp>
        </div>

        <FadeUp delay={0.1} className="lg:col-span-6 lg:col-start-7">
          <form onSubmit={submit} className="flex flex-col gap-8">
            <div className="flex flex-col gap-8 sm:flex-row">
              <label className="flex-1 flex flex-col gap-2">
                <span className="text-[11px] tracking-[0.2em] uppercase text-white/40">Your Name</span>
                <input
                  data-testid={CONTACT.nameInput}
                  value={form.name}
                  onChange={update('name')}
                  placeholder="Jane Director"
                  className="bg-transparent border-b border-white/20 py-3 text-lg focus:border-[#E11D48] outline-none transition-colors placeholder:text-white/25"
                />
              </label>
              <label className="flex-1 flex flex-col gap-2">
                <span className="text-[11px] tracking-[0.2em] uppercase text-white/40">Email</span>
                <input
                  data-testid={CONTACT.emailInput}
                  type="email"
                  value={form.email}
                  onChange={update('email')}
                  placeholder="you@email.com"
                  className="bg-transparent border-b border-white/20 py-3 text-lg focus:border-[#E11D48] outline-none transition-colors placeholder:text-white/25"
                />
              </label>
            </div>
            <label className="flex flex-col gap-2">
              <span className="text-[11px] tracking-[0.2em] uppercase text-white/40">Message</span>
              <textarea
                data-testid={CONTACT.messageInput}
                value={form.message}
                onChange={update('message')}
                rows={4}
                placeholder="Tell us about your project..."
                className="bg-transparent border-b border-white/20 py-3 text-lg focus:border-[#E11D48] outline-none transition-colors resize-none placeholder:text-white/25"
              />
            </label>

            <motion.button
              type="submit"
              data-testid={CONTACT.submit}
              disabled={loading}
              whileHover={{ scale: loading ? 1 : 1.02 }}
              whileTap={{ scale: 0.98 }}
              className="self-start mt-4 bg-white text-black rounded-full px-10 py-4 text-xs tracking-[0.25em] uppercase font-medium hover:bg-[#E11D48] hover:text-white transition-colors duration-300 disabled:opacity-50"
            >
              {loading ? 'Sending...' : 'Send Message'}
            </motion.button>
          </form>
        </FadeUp>
      </div>
    </section>
  );
};
